1.query:
fetch logs
| filter service.name == "cart" and loglevel == "INFO" and matchesPhrase(content, "Item added")
| summarize added = count(), by:{bin(timestamp, 1h)}

2.query:
fetch spans
| filter service.name == "cart" and span.name == "CartService/AddItem"
| summarize calls = count(), by:{bin(start_time, 1h)}
